'use client';

import { useState } from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  User,
  LayoutGrid,
  ShieldCheck,
  PlusCircle,
} from 'lucide-react';
import { toast } from 'sonner';
import { usePersonnel } from '@/hooks/use-personnel';
import { useRoles } from '@/hooks/use-roles';
import { useDepartments } from '@/hooks/use-departments';
import { useGuards } from '@/hooks/use-guards';
import { useUnits } from '@/hooks/use-units';
import { useWorkspaceManager } from '@/lib/db/db-context';
import { useReports } from '@/hooks/use-reports';
import type { StaffMember } from '@/types';
import { StructureManager } from '@/components/structure-manager';
import { DataTableSkeleton } from '@/components/ui/loading-skeleton';
import { FeatureErrorBoundary } from '@/components/error-boundary-feature';

// Extracted components
import { PersonnelTable } from '@/components/personnel/personnel-table';
import { AddEditPersonnelDialog } from '@/components/personnel/add-edit-personnel-dialog';

import { GuardAssignmentPanel } from '@/components/personnel/guard-assignment-panel';
import { PersonnelHistoryDialog } from '@/components/personnel/personnel-history-dialog';
import { CsvImportButton } from '@/components/personnel/csv-import-button';

import { ConfirmDialog } from '@/components/ui/confirm-dialog';
import { Trash2, Car } from 'lucide-react';
import { UnitsManager } from '@/components/personnel/units-manager';

function PersonnelPageContent() {
  // Hooks
  const {
    personnel,
    addMember,
    addMembers,
    updateMember,
    removeMember,
    removeMembers,
    isLoaded: personnelLoaded,
    isCedulaDuplicate,
  } = usePersonnel();
  const { roles, saveRoles, isLoaded: rolesLoaded } = useRoles();
  const { currentWorkspace } = useWorkspaceManager();
  const { departments, saveDepartments, isLoaded: deptsLoaded } = useDepartments();
  const { guards, saveGuards, isLoaded: guardsLoaded } = useGuards();
  const { units, isLoaded: unitsLoaded } = useUnits();

  useReports();

  // Dialog state
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingMember, setEditingMember] = useState<StaffMember | null>(null);
  const [viewHistoryMember, setViewHistoryMember] = useState<StaffMember | null>(null);
  const [isHistoryDialogOpen, setIsHistoryDialogOpen] = useState(false);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [isBulkDeleteConfirmOpen, setIsBulkDeleteConfirmOpen] = useState(false);



  // Loading state
  const isLoading =
    !personnelLoaded || !rolesLoaded || !deptsLoaded || !guardsLoaded || !unitsLoaded;

  if (isLoading) {
    return (
      <div className="container mx-auto p-8">
        <div className="mb-6">
          <h1 className="text-3xl font-bold">Personal</h1>
          <p className="text-muted-foreground">Cargando datos...</p>
        </div>
        <DataTableSkeleton rows={10} columns={5} />
      </div>
    );
  }

  // Handlers
  const handleEdit = (member: StaffMember) => {
    setEditingMember(member);
    setIsDialogOpen(true);
  };

  const handleAddNew = () => {
    setEditingMember(null);
    setIsDialogOpen(true);
  };

  const handleSave = async (data: Partial<StaffMember>) => {
    // Validation: Cédula duplicate
    if (data.cedula && isCedulaDuplicate(data.cedula, editingMember?.id)) {
      toast.error('Ya existe una persona registrada con esta cédula');
      return;
    }

    if (editingMember) {
      // Update existing
      await updateMember(editingMember.id, data);
      toast.success('Cambios guardados');
    } else {
      // Add new - ensure name is provided
      if (data.name) {
        const newMemberData: Omit<StaffMember, 'id'> = {
          workspaceId: currentWorkspace,
          name: data.name,
          cedula: data.cedula || '',
          rank: data.rank || '',
          department: data.department || '',
        };
        await addMember(newMemberData);
        toast.success('Personal añadido');
      }
    }
    setIsDialogOpen(false);
    setEditingMember(null);
  };

  const handleCancel = () => {
    setIsDialogOpen(false);
    setEditingMember(null);
  };

  const handleDelete = (id: string) => {
    removeMember(id);
    setSelectedIds((prev) => prev.filter((selectedId) => selectedId !== id));
    toast.success('Personal eliminado');
  };

  const handleBulkDelete = () => {
    if (selectedIds.length === 0) return;
    removeMembers(selectedIds);
    setSelectedIds([]);
    setIsBulkDeleteConfirmOpen(false);
    toast.success(`${selectedIds.length} personas eliminadas`);
  };

  const handleViewHistory = (member: StaffMember) => {
    setViewHistoryMember(member);
    setIsHistoryDialogOpen(true);
  };



  return (
    <div className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-10 py-8 pb-24 sm:pb-12 h-full">
      <div className="flex flex-col lg:flex-row gap-10 items-start">
        {/* Left Sidebar - Stats & Insights (Desktop Only) */}
        <aside className="hidden lg:flex w-80 flex-col gap-6 sticky top-8">
          <div className="space-y-2">
            <h1 className="text-4xl font-bold tracking-tight">Personal</h1>
            <p className="text-muted-foreground text-sm leading-relaxed">
              Gestión centralizada de funcionarios, departamentos y asignación de guardias.
            </p>
          </div>

          <div className="grid grid-cols-1 gap-4">
            <StatsCard 
              label="Total Funcionarios" 
              value={personnel.length} 
              icon={<User className="h-5 w-5 text-primary" />} 
              description="Registrados en el sistema"
            />
            <StatsCard 
              label="Departamentos" 
              value={departments.length} 
              icon={<LayoutGrid className="h-5 w-5 text-primary" />} 
              description="Unidades operativas"
            />
            <StatsCard 
              label="Roles y Cargos" 
              value={roles.length} 
              icon={<ShieldCheck className="h-5 w-5 text-primary" />} 
              description="Niveles de jerarquía"
            />
            <StatsCard 
              label="Unidades" 
              value={units.length} 
              icon={<Car className="h-5 w-5 text-primary" />} 
              description="Vehículos operativos"
            />
          </div>

          <Card className="bg-primary/5 border-primary/20 shadow-none">
            <CardContent className="p-5 space-y-4">
              <h3 className="font-semibold text-sm">Acciones Rápidas</h3>
              <div className="grid gap-2">
                <CsvImportButton onImport={addMembers} personnel={personnel} />
                <Button onClick={handleAddNew} className="w-full justify-start gap-2 shadow-sm">
                  <PlusCircle className="h-4 w-4" />
                  Añadir Personal
                </Button>
              </div>
            </CardContent>
          </Card>
        </aside>

        {/* Main Content Area */}
        <div className="flex-1 w-full space-y-8">
          {/* Mobile Header (Hidden on LG+) */}
          <div className="lg:hidden flex flex-col gap-4 mb-6">
            <div>
              <h1 className="text-3xl font-bold">Personal</h1>
              <p className="text-muted-foreground text-sm">Administra el talento humano de la organización.</p>
            </div>
            <div className="flex flex-wrap items-center gap-2">
              <CsvImportButton onImport={addMembers} personnel={personnel} />
              <Button size="sm" onClick={handleAddNew} className="h-9 gap-2 shadow-sm">
                <PlusCircle className="h-4 w-4" />
                Personal
              </Button>
            </div>
          </div>

          {/* Bulk Actions Bar */}
          {selectedIds.length > 0 && (
            <div className="flex items-center justify-between p-4 bg-destructive/10 border border-destructive/20 rounded-xl animate-in fade-in slide-in-from-top-4 duration-300">
              <span className="text-sm font-medium text-destructive-foreground">
                {selectedIds.length} funcionarios seleccionados
              </span>
              <Button
                variant="destructive"
                size="sm"
                onClick={() => setIsBulkDeleteConfirmOpen(true)}
                className="shadow-sm h-8"
              >
                <Trash2 className="mr-2 h-4 w-4" />
                Eliminar Permanentes
              </Button>
            </div>
          )}

          {/* Tabbed Interface */}
          <Tabs defaultValue="personnel" className="space-y-6">
            <div className="overflow-x-auto pb-1 -mx-4 px-4 sm:mx-0 sm:px-0">
              <TabsList className="flex w-max sm:grid sm:w-full sm:grid-cols-4 sm:max-w-xl bg-muted/50 p-1">
                <TabsTrigger value="personnel" className="flex items-center gap-2 px-4 py-2 ring-offset-background transition-all data-[state=active]:bg-background data-[state=active]:shadow-sm">
                  <User className="h-4 w-4" />
                  <span className="font-medium">Funcionarios</span>
                </TabsTrigger>
                <TabsTrigger value="structure" className="flex items-center gap-2 px-4 py-2 transition-all data-[state=active]:bg-background data-[state=active]:shadow-sm">
                  <LayoutGrid className="h-4 w-4" />
                  <span className="font-medium">Estructura</span>
                </TabsTrigger>
                <TabsTrigger value="guards" className="flex items-center gap-2 px-4 py-2 transition-all data-[state=active]:bg-background data-[state=active]:shadow-sm">
                  <ShieldCheck className="h-4 w-4" />
                  <span className="font-medium">Guardias</span>
                </TabsTrigger>
                <TabsTrigger value="units" className="flex items-center gap-2 px-4 py-2 transition-all data-[state=active]:bg-background data-[state=active]:shadow-sm">
                  <Car className="h-4 w-4" />
                  <span className="font-medium">Unidades</span>
                </TabsTrigger>
              </TabsList>
            </div>

            <TabsContent value="personnel" className="mt-0 focus-visible:outline-none ring-offset-background">
              <Card className="border-none shadow-xl shadow-foreground/5 bg-card overflow-hidden">
                <CardContent className="p-0 sm:p-6">
                  <PersonnelTable
                    personnel={personnel}
                    departments={departments}
                    onEdit={handleEdit}
                    onDelete={handleDelete}
                    onViewHistory={handleViewHistory}
                    selectedIds={selectedIds}
                    onSelectionChange={setSelectedIds}
                  />
                </CardContent>
              </Card>
            </TabsContent>

            <TabsContent value="structure" className="mt-0 focus-visible:outline-none">
              <StructureManager
                roles={roles}
                departments={departments}
                onRolesChange={saveRoles}
                onDepartmentsChange={saveDepartments}
                onSave={() => { }}
              />
            </TabsContent>

            <TabsContent value="guards" className="mt-0 focus-visible:outline-none">
              <GuardAssignmentPanel
                guards={guards}
                personnel={personnel}
                roles={roles}
                onGuardUpdate={saveGuards}
              />
            </TabsContent>

            <TabsContent value="units" className="mt-0 focus-visible:outline-none">
              <UnitsManager />
            </TabsContent>
          </Tabs>
        </div>
      </div>

      {/* Add/Edit Dialog */}
      <AddEditPersonnelDialog
        open={isDialogOpen}
        member={editingMember}
        roles={roles}
        departments={departments}
        onSave={handleSave}
        onCancel={handleCancel}
      />

      <ConfirmDialog
        open={isBulkDeleteConfirmOpen}
        onOpenChange={setIsBulkDeleteConfirmOpen}
        title="¿Eliminar personal seleccionado?"
        message={`Estás a punto de eliminar a ${selectedIds.length} personas. Esta acción no se puede deshacer.`}
        onConfirm={handleBulkDelete}
        variant="destructive"
      />
      <PersonnelHistoryDialog
        member={viewHistoryMember}
        isOpen={isHistoryDialogOpen}
        onClose={() => {
          setIsHistoryDialogOpen(false);
          setViewHistoryMember(null);
        }}
      />
    </div>
  );
}

function StatsCard({ 
  label, 
  value, 
  icon, 
  description 
}: { 
  label: string; 
  value: number; 
  icon: React.ReactNode; 
  description: string;
}) {
  return (
    <Card className="border-none shadow-sm bg-muted/20">
      <CardContent className="p-4 flex items-center gap-4">
        <div className="p-2.5 rounded-xl bg-background shadow-sm border border-border/50">
          {icon}
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-[10px] uppercase tracking-wider font-semibold text-muted-foreground mb-0.5">{label}</p>
          <div className="flex items-baseline gap-2">
            <span className="text-2xl font-bold">{value}</span>
            <span className="text-[10px] text-muted-foreground truncate">{description}</span>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

export default function PersonnelPage() {
  return (
    <FeatureErrorBoundary featureName="Personal">
      <PersonnelPageContent />
    </FeatureErrorBoundary>
  );
}
